import { IMAGE_CAPABILITIES } from "../../core/engine.js";
import type { EngineContext, PlayerEngine } from "../../core/engine.js";
import { createPlayerError } from "../../core/errors.js";
import { collectChunks } from "../shared/chunks.js";
import { removeElement } from "../shared/dom.js";

/** Still-image engine. */
export function createImageEngine(context: EngineContext): PlayerEngine {
  const { source, emit } = context;
  let image: HTMLImageElement | null = null;
  let objectUrl: string | null = null;

  return {
    kind: "image",
    get element() {
      return image;
    },
    capabilities: IMAGE_CAPABILITIES,

    async load(): Promise<void> {
      const element = document.createElement("img");

      element.className = "up-media up-image";
      element.setAttribute("part", "media");
      element.decoding = "async";
      element.loading = "eager";
      element.alt = "alt" in source.source ? (source.source.alt ?? "") : "";
      image = element;
      context.host.append(element);

      let url = source.url;

      if (source.chunks !== null) {
        const blob = await collectChunks(
          source.chunks,
          source.mimeType ?? "image/*",
          "chunkDelay" in source.source ? source.source.chunkDelay : 0,
        );

        if (typeof URL.createObjectURL === "function") {
          objectUrl = URL.createObjectURL(blob);
          url = objectUrl;
        }
      }

      await new Promise<void>((resolve, reject) => {
        element.addEventListener("load", () => resolve(), { once: true });
        element.addEventListener(
          "error",
          () =>
            reject(
              createPlayerError("The image could not be loaded.", {
                code: "media-error",
                details: { source: url },
              }),
            ),
          { once: true },
        );
        element.src = url;
      });

      emit("loadedmetadata", {
        duration: 0,
        width: element.naturalWidth,
        height: element.naturalHeight,
        live: false,
      });
    },

    async play(): Promise<void> {
      // A still image has no playback.
    },

    pause(): void {
      // A still image has no playback.
    },

    seek(): void {
      // A still image has no timeline.
    },

    setVolume(): void {
      // A still image has no audio.
    },

    setMuted(): void {
      // A still image has no audio.
    },

    setPlaybackRate(): void {
      // A still image has no playback rate.
    },

    getQualities(): readonly [] {
      return [];
    },

    getTextTracks(): readonly [] {
      return [];
    },

    getAudioTracks(): readonly [] {
      return [];
    },

    getCurrentTime(): number {
      return 0;
    },

    getDuration(): number {
      return 0;
    },

    getBuffered(): number {
      return 0;
    },

    destroy(): void {
      removeElement(image);
      image = null;

      if (objectUrl !== null && typeof URL.revokeObjectURL === "function") {
        URL.revokeObjectURL(objectUrl);
        objectUrl = null;
      }
    },
  };
}
